func _on_body_entered(body: Node) -> void:
	if body is PlayerController:
		GameManager.set_area(area_id)

extends Camera2D
class_name CameraRig

@export var target_path: NodePath
@export var look_ahead_distance: float = 95.0
@export var smooth_speed: float = 5.2
@export var base_zoom: float = 1.06

var _target: Node2D
var _shake_strength: float = 0.0
var _target_zoom: float = 1.06
var _base_pos: Vector2 = Vector2(160.0, 340.0)
var _focus_timer: float = 0.0
var _focus_pos: Vector2 = Vector2.ZERO
var _focus_zoom: float = 1.06

func _ready() -> void:
	zoom = Vector2(base_zoom, base_zoom)
	if not target_path.is_empty():
		_target = get_node_or_null(target_path)
	ResonanceSystem.state_changed.connect(_on_state_changed)
	GameManager.area_changed.connect(_on_area_changed)
	GameManager.cinematic_focus_requested.connect(_on_cinematic_focus)

func _process(delta: float) -> void:
	if _target == null and _focus_timer <= 0.0:
		return

	var desired := _base_pos
	var desired_zoom := _target_zoom
	if _focus_timer > 0.0:
		_focus_timer = maxf(0.0, _focus_timer - delta)
		desired = _focus_pos
		desired_zoom = _focus_zoom
	elif _target != null:
		var vel_x := 0.0
		if _target is CharacterBody2D:
			vel_x = (_target as CharacterBody2D).velocity.x
		var ahead := clampf(vel_x * 0.26, -look_ahead_distance, look_ahead_distance)
		desired = Vector2(_target.global_position.x + ahead, _target.global_position.y - 38.0)

	_base_pos = _base_pos.lerp(desired, clampf(smooth_speed * delta, 0.0, 1.0))

	var z := lerpf(zoom.x, desired_zoom, 2.8 * delta)
	zoom = Vector2(z, z)

	if _shake_strength > 0.15:
		offset = Vector2(
			randf_range(-_shake_strength, _shake_strength),
			randf_range(-_shake_strength, _shake_strength)
		)
		_shake_strength = lerpf(_shake_strength, 0.0, 10.0 * delta)
	else:
		offset = Vector2.ZERO

	global_position = _base_pos

func add_shake(amount: float) -> void:
	_shake_strength = maxf(_shake_strength, amount)

func _on_cinematic_focus(world_pos: Vector2, target_z: float, duration: float, _use_letterbox: bool) -> void:
	_focus_pos = world_pos
	_focus_zoom = target_z
	_focus_timer = duration

func _on_state_changed(new_state: int, _prev: int) -> void:
	if new_state == ResonanceSystem.State.RUPTURA:
		add_shake(7.5)
	elif new_state == ResonanceSystem.State.ECO:
		add_shake(3.0)

func _on_area_changed(area_id: int, _title: String, _sub: String) -> void:
	# Enquadramento cinematográfico mais amplo em O Chamado (Área 5) e A Convergência (Área 10)
	_target_zoom = 0.84 if (area_id == 5 or area_id == 10) else base_zoom

extends Node

# Progressão completa entre Capítulos I a VI
signal memory_unlocked(memory_id: String, total_found: int)

const CHAPTER_SCENES := {
	1: "res://scenes/world_chapter_1.tscn",
	2: "res://scenes/world_chapter_2_threshold.tscn",
	3: "res://scenes/world_chapter_3_city.tscn",
	4: "res://scenes/world_chapter_4_abyss.tscn",
	5: "res://scenes/world_chapter_5_convergence.tscn",
	6: "res://scenes/world_chapter_6_threshold.tscn"
}

const CHAPTER_MEMORIES_TOTAL := {
	1: 4,
	2: 5,
	3: 4,
	4: 4,
	5: 4,
	6: 4
}

const CHAPTER_TITLES := {
	1: {"roman": "I", "title": "O Despertar", "subtitle": "Ruínas do Subsolo"},
	2: {"roman": "II", "title": "O Chamado", "subtitle": "Torres Invertidas"},
	3: {"roman": "III", "title": "A Cidade Esquecida", "subtitle": "Arcos Submersos"},
	4: {"roman": "IV", "title": "O Abismo das Memórias", "subtitle": "Ecos Profundos"},
	5: {"roman": "V", "title": "A Convergência", "subtitle": "O Núcleo Industrial"},
	6: {"roman": "VI", "title": "O Limiar da Existência", "subtitle": "O Vértice Final"}
}

var unlocked_chapter: int = 1
var completed_chapters: Array[int] = []
var discovered_memories: PackedStringArray = PackedStringArray()

# Aliases de compatibilidade com scripts legados
const CHAPTER_I_SCENE := "res://scenes/world_chapter_1.tscn"
const CHAPTER_II_SCENE := "res://scenes/world_chapter_2_threshold.tscn"
var chapter_1_completed: bool = false
var chapter_2_completed: bool = false

func _ready() -> void:
	load_from_save(SaveManager.data)

func get_scene_path(chapter_num: int) -> String:
	return str(CHAPTER_SCENES.get(clampi(chapter_num, 1, 6), CHAPTER_SCENES[1]))

func _memory_belongs_to_chapter(mem_id: String, chapter_num: int) -> bool:
	if chapter_num == 1:
		return not mem_id.begins_with("mem_c")
	return mem_id.begins_with("mem_c%d_" % chapter_num)

func register_memory(memory_id: String) -> void:
	if memory_id.is_empty() or discovered_memories.has(memory_id):
		return
	discovered_memories.append(memory_id)
	emit_signal("memory_unlocked", memory_id, get_chapter_memory_count(GameManager.current_chapter))
	SaveManager.save_progress()

func get_chapter_memory_count(chapter_or_c2) -> int:
	var chap := 2 if (typeof(chapter_or_c2) == TYPE_BOOL and chapter_or_c2) else (1 if typeof(chapter_or_c2) == TYPE_BOOL else int(chapter_or_c2))
	var c := 0
	for m in discovered_memories:
		if _memory_belongs_to_chapter(m, chap):
			c += 1
	return c

func get_chapter_memory_total(chapter_or_c2) -> int:
	var chap := 2 if (typeof(chapter_or_c2) == TYPE_BOOL and chapter_or_c2) else (1 if typeof(chapter_or_c2) == TYPE_BOOL else int(chapter_or_c2))
	return int(CHAPTER_MEMORIES_TOTAL.get(chap, 4))

func mark_chapter_completed(chapter_num: int) -> void:
	var chap := clampi(chapter_num, 1, 6)
	if not completed_chapters.has(chap):
		completed_chapters.append(chap)
	if chap == 1:
		chapter_1_completed = true
	elif chap == 2:
		chapter_2_completed = true
	if chap < 6:
		unlocked_chapter = maxi(unlocked_chapter, chap + 1)
	SaveManager.save_progress()

func mark_chapter_1_completed() -> void:
	mark_chapter_completed(1)

func mark_chapter_2_completed() -> void:
	mark_chapter_completed(2)

func is_chapter_unlocked(chapter_num: int) -> bool:
	return chapter_num <= unlocked_chapter

func reset_progression() -> void:
	unlocked_chapter = 1
	completed_chapters.clear()
	chapter_1_completed = false
	chapter_2_completed = false
	discovered_memories.clear()

func load_from_save(data: Dictionary) -> void:
	chapter_1_completed = bool(data.get("chapter_1_completed", false))
	chapter_2_completed = bool(data.get("chapter_2_completed", false))
	unlocked_chapter = clampi(int(data.get("unlocked_chapter", 2 if chapter_1_completed else 1)), 1, 6)

	completed_chapters.clear()
	var comp = data.get("completed_chapters", [])
	if typeof(comp) == TYPE_ARRAY:
		for item in comp:
			var cid := clampi(int(item), 1, 6)
			if not completed_chapters.has(cid):
				completed_chapters.append(cid)
	if chapter_1_completed and not completed_chapters.has(1):
		completed_chapters.append(1)
	if chapter_2_completed and not completed_chapters.has(2):
		completed_chapters.append(2)

	var arr = data.get("discovered_memories", [])
	discovered_memories.clear()
	if typeof(arr) == TYPE_ARRAY:
		for item in arr:
			var s := str(item)
			if not s.is_empty() and not discovered_memories.has(s):
				discovered_memories.append(s)

func serialize() -> Dictionary:
	var mem_arr: Array[String] = []
	for m in discovered_memories:
		mem_arr.append(m)
	var comp_arr: Array[int] = []
	for c in completed_chapters:
		comp_arr.append(c)
	return {
		"unlocked_chapter": unlocked_chapter,
		"completed_chapters": comp_arr,
		"chapter_1_completed": chapter_1_completed,
		"chapter_2_completed": chapter_2_completed,
		"discovered_memories": mem_arr
	}

func transition_to_chapter_2() -> void:
	GameManager.start_chapter(2)

extends Area2D
class_name Checkpoint

@export var checkpoint_id: String = "cp_area_1"
@export var area_id: int = 1

var _ignited: bool = false
var _t: float = 0.0

@onready var lantern_light: PointLight2D = $LanternLight
@onready var orb_poly: Polygon2D = $OrbPoly

func _ready() -> void:
	body_entered.connect(_on_body_entered)
	_ignited = (GameManager.active_checkpoint_id == checkpoint_id and SaveManager.has_saved_game()) or (area_id < GameManager.current_area and SaveManager.has_saved_game())
	if lantern_light:
		lantern_light.texture = TextureFactory2D.tex_core_glow
		lantern_light.energy = 1.9 if _ignited else 0.45
	if orb_poly:
		orb_poly.color = Color(1.0, 0.78, 0.42, 1.0) if _ignited else Color(0.52, 0.58, 0.68, 1.0)

func _process(delta: float) -> void:
	_t += delta
	if not _ignited:
		for body in get_overlapping_bodies():
			if body is PlayerController and (body as PlayerController).is_on_floor() and (body as PlayerController).velocity.y <= 80.0:
				_ignite()
				break
	if _ignited:
		queue_redraw()

func _draw() -> void:
	if not _ignited:
		return
	var r := 14.0 + sin(_t * 3.2) * 1.6
	draw_arc(Vector2(0.0, -64.0), r, 0.0, TAU, 20, Color(1.0, 0.74, 0.36, 0.42), 1.4)

func _on_body_entered(body: Node) -> void:
	if body is PlayerController and not _ignited:
		if (body as PlayerController).is_on_floor() and (body as PlayerController).velocity.y <= 80.0:
			_ignite()

func _ignite() -> void:
	_ignited = true
	if lantern_light:
		lantern_light.energy = 1.9
	if orb_poly:
		orb_poly.color = Color(1.0, 0.78, 0.42, 1.0)
	GameManager.register_checkpoint(checkpoint_id, global_position + Vector2(0.0, -6.0), area_id)
	AudioManager.play_sfx("checkpoint", 1.0)

extends Area2D
class_name ClimbZone

@export var zone_width: float = 28.0
@export var zone_height: float = 180.0
@export var is_rope: bool = true

var _t: float = 0.0

func _ready() -> void:
	collision_layer = 4
	collision_mask = 2
	var col := CollisionShape2D.new()
	var rect := RectangleShape2D.new()
	rect.size = Vector2(zone_width, zone_height)
	col.shape = rect
	col.position = Vector2(0.0, -zone_height * 0.5)
	add_child(col)
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)

func _process(delta: float) -> void:
	_t += delta
	queue_redraw()

func _draw() -> void:
	if is_rope:
		var sway := sin(_t * 1.4) * 2.5
		draw_line(Vector2(0.0, -zone_height), Vector2(sway, 0.0), Color(0.45, 0.42, 0.38, 0.9), 3.0)
		var y := -16.0
		while y > -zone_height + 10.0:
			draw_circle(Vector2(sway * (1.0 + y / zone_height), y), 2.2, Color(0.75, 0.65, 0.48, 0.7))
			y -= 28.0
	else:
		draw_line(Vector2(-8.0, -zone_height), Vector2(-8.0, 0.0), Color(0.24, 0.28, 0.35, 0.95), 2.5)
		draw_line(Vector2(8.0, -zone_height), Vector2(8.0, 0.0), Color(0.24, 0.28, 0.35, 0.95), 2.5)
		var ry := -18.0
		while ry > -zone_height + 12.0:
			draw_line(Vector2(-8.0, ry), Vector2(8.0, ry), Color(0.38, 0.43, 0.52, 0.9), 2.0)
			ry -= 22.0

func _on_body_entered(body: Node) -> void:
	if body is PlayerController:
		(body as PlayerController).set_climb_zone(self, true)

func _on_body_exited(body: Node) -> void:
	if body is PlayerController:
		(body as PlayerController).set_climb_zone(self, false)

extends Node2D
class_name CreatureEntity

enum Kind { VEIL_WISP = 0, HOLLOW_WARDEN = 1, ARCHIVE_STALKER = 2 }

@export var kind: Kind = Kind.VEIL_WISP
@export var patrol_min_x: float = -120.0
@export var patrol_max_x: float = 120.0
@export var base_speed: float = 55.0

var _origin_x: float = 0.0
var _dir: float = 1.0
var _t: float = 0.0
var _alert_level: float = 0.0
var _state: String = "patrol" # patrol | alert | calmed

func _ready() -> void:
	_origin_x = global_position.x
	if patrol_min_x > patrol_max_x:
		var tmp := patrol_min_x
		patrol_min_x = patrol_max_x
		patrol_max_x = tmp

func _physics_process(delta: float) -> void:
	_t += delta
	var players := get_tree().get_nodes_in_group("player")
	var player: PlayerController = players[0] as PlayerController if not players.is_empty() and players[0] is PlayerController else null

	var in_echo := ResonanceSystem.current_state == ResonanceSystem.State.ECO
	if kind == Kind.VEIL_WISP:
		_state = "calmed" if in_echo else "patrol"
		global_position.x += _dir * base_speed * (0.55 if in_echo else 1.0) * delta
		if global_position.x >= patrol_max_x:
			global_position.x = patrol_max_x
			_dir = -1.0
		elif global_position.x <= patrol_min_x:
			global_position.x = patrol_min_x
			_dir = 1.0
		global_position.y += sin(_t * 2.4) * 18.0 * delta
		if player and not player.is_recovering() and not in_echo:
			var dist := global_position.distance_to(player.global_position + Vector2(0, -26))
			if dist < 24.0:
				player.trigger_death_recover()
	else:
		var crouched := player != null and player.is_crouching()
		var detect_range := (115.0 if crouched else 245.0) if kind == Kind.HOLLOW_WARDEN else (140.0 if crouched else 290.0)
		var detected := false
		if player and not player.is_recovering():
			var d := global_position.distance_to(player.global_position + Vector2(0, -26))
			var same_height := absf(player.global_position.y - global_position.y) < 110.0
			var facing_player := (player.global_position.x - global_position.x) * _dir > -36.0
			if in_echo and kind == Kind.HOLLOW_WARDEN:
				detected = false
			elif d < detect_range and same_height and (facing_player or d < 85.0):
				detected = true

		if detected:
			_alert_level = minf(1.0, _alert_level + delta * 1.3)
			_state = "alert"
			_dir = signf(player.global_position.x - global_position.x)
			if _dir == 0.0:
				_dir = 1.0
			global_position.x = clampf(global_position.x + _dir * base_speed * 1.45 * delta, patrol_min_x, patrol_max_x)
			var contact := global_position.distance_to(player.global_position + Vector2(0, -26))
			if contact < 26.0:
				player.trigger_death_recover()
		else:
			_alert_level = maxf(0.0, _alert_level - delta * 0.7)
			_state = "calmed" if in_echo else "patrol"
			global_position.x += _dir * base_speed * delta
			if global_position.x >= patrol_max_x:
				global_position.x = patrol_max_x
				_dir = -1.0
			elif global_position.x <= patrol_min_x:
				global_position.x = patrol_min_x
				_dir = 1.0
	queue_redraw()

func _draw() -> void:
	var pulse := 0.5 + 0.5 * sin(_t * 3.4)
	if kind == Kind.VEIL_WISP:
		var col := Color(0.95, 0.72, 0.34, 0.86) if _state == "calmed" else Color(0.58, 0.80, 0.96, 0.82)
		draw_circle(Vector2.ZERO, 18.0 + pulse * 4.0, Color(col.r, col.g, col.b, 0.14))
		draw_circle(Vector2.ZERO, 7.0, col)
		draw_line(Vector2.ZERO, Vector2(-_dir * 26.0, sin(_t * 4.0) * 6.0), Color(col.r, col.g, col.b, 0.45), 2.5)
	elif kind == Kind.HOLLOW_WARDEN:
		var eye := Color(0.96, 0.36, 0.24, 0.95) if _state == "alert" else (Color(0.95, 0.72, 0.34, 0.85) if _state == "calmed" else Color(0.84, 0.68, 0.46, 0.75))
		var body_pts := PackedVector2Array([
			Vector2(-14, 0), Vector2(14, 0), Vector2(10, -48), Vector2(3, -64), Vector2(-6, -60), Vector2(-12, -40)
		])
		draw_colored_polygon(body_pts, Color(0.04, 0.05, 0.08, 0.96))
		draw_circle(Vector2(_dir * 4.0, -54.0), 3.0 + pulse * 0.8, eye)
		if _state != "calmed":
			var cone_len := 180.0 if _state == "alert" else 130.0
			var cone := PackedVector2Array([
				Vector2(_dir * 5.0, -54.0),
				Vector2(_dir * cone_len, -76.0),
				Vector2(_dir * cone_len, -10.0)
			])
			draw_colored_polygon(cone, Color(eye.r, eye.g, eye.b, 0.14 if _state == "alert" else 0.07))
	else:
		# Archive Stalker
		var eye := Color(0.96, 0.32, 0.24, 0.96) if _state == "alert" else Color(0.92, 0.62, 0.28, 0.82)
		var pts := PackedVector2Array([
			Vector2(-18, 0), Vector2(-6, -24), Vector2(10, -26), Vector2(20, 0), Vector2(6, -12), Vector2(-6, -12)
		])
		draw_colored_polygon(pts, Color(0.05, 0.06, 0.09, 0.96))
		draw_circle(Vector2(_dir * 12.0, -20.0), 2.8 + pulse * 0.7, eye)

