extends StaticBody2D
class_name ResonanceObject

enum Mode {
	ALWAYS_SOLID = 0,
	ECHO_ONLY = 1,
	PRESENT_ONLY = 2,
	RUPTURA_SHIFT = 3
}

@export var object_mode: Mode = Mode.ECHO_ONLY
@export var size: Vector2 = Vector2(220.0, 36.0)
@export var ruptura_offset: Vector2 = Vector2(0.0, -155.0)
@export var shift_speed: float = 5.2
@export var move_offset: Vector2 = Vector2.ZERO
@export var move_period: float = 0.0
@export var move_phase: float = 0.0
@export var use_wet_concrete: bool = false
@export var use_oxidized_metal: bool = false

var _origin_pos: Vector2
var _target_pos: Vector2
var _shader_mat: ShaderMaterial
var _visual_rect: TextureRect
var _elapsed: float = 0.0

@onready var collision_shape: CollisionShape2D = $CollisionShape2D

func _ready() -> void:
	add_to_group("resonance_objects")
	_origin_pos = position
	_target_pos = _origin_pos
	_setup_visual_2d()
	ResonanceSystem.state_changed.connect(_on_state_changed)
	_apply_state(ResonanceSystem.current_state)

func _setup_visual_2d() -> void:
	_visual_rect = TextureRect.new()
	_visual_rect.size = size
	_visual_rect.position = -size * 0.5
	_visual_rect.stretch_mode = TextureRect.STRETCH_TILE
	_visual_rect.texture_repeat = CanvasItem.TEXTURE_REPEAT_ENABLED
	if use_oxidized_metal:
		_visual_rect.texture = TextureFactory2D.tex_oxidized_metal
	elif use_wet_concrete:
		_visual_rect.texture = TextureFactory2D.tex_wet_concrete
	else:
		_visual_rect.texture = TextureFactory2D.tex_concrete

	if object_mode != Mode.ALWAYS_SOLID:
		_shader_mat = ShaderMaterial.new()
		_shader_mat.shader = load("res://shaders/resonance_shift.gdshader")
		_visual_rect.material = _shader_mat

	add_child(_visual_rect)
	queue_redraw()

func _draw() -> void:
	var half := size * 0.5
	if object_mode == Mode.ALWAYS_SOLID and size.x >= 140.0 and size.y < 180.0 and move_period <= 0.0:
		var sx := -half.x + 26.0
		while sx < half.x - 20.0:
			draw_rect(Rect2(sx, half.y, 12.0, 220.0), Color(0.035, 0.047, 0.068, 0.96))
			draw_rect(Rect2(sx, half.y, 2.0, 220.0), Color(0.35, 0.42, 0.52, 0.12))
			sx += 180.0
	if object_mode == Mode.ALWAYS_SOLID or object_mode == Mode.RUPTURA_SHIFT:
		draw_rect(Rect2(-half.x, half.y - 3.5, size.x, 3.5), Color(0.01, 0.015, 0.025, 0.58))
		var rim_col := Color(0.60, 0.72, 0.88, 0.34) if use_wet_concrete else (Color(0.72, 0.58, 0.45, 0.28) if use_oxidized_metal else Color(0.50, 0.56, 0.66, 0.22))
		draw_rect(Rect2(-half.x, -half.y, size.x, 2.5), rim_col)
		if move_period > 0.0:
			draw_rect(Rect2(-12.0, -2.0, 24.0, 4.0), Color(0.90, 0.60, 0.22, 0.55))

func _physics_process(delta: float) -> void:
	if delta <= 0.0:
		return
	var prev_pos := position
	if object_mode == Mode.RUPTURA_SHIFT:
		position = position.lerp(_target_pos, clampf(shift_speed * delta, 0.0, 1.0))
		constant_linear_velocity = (position - prev_pos) / delta
	elif move_period > 0.0 and (move_offset.x != 0.0 or move_offset.y != 0.0):
		_elapsed += delta
		var omega := TAU / move_period
		var frac := 0.5 - 0.5 * cos(_elapsed * omega + move_phase)
		position = _origin_pos + move_offset * frac
		constant_linear_velocity = (position - prev_pos) / delta

func would_block_rect_in_state(world_rect: Rect2, target_state: int) -> bool:
	var solid_in_target := false
	match object_mode:
		Mode.ALWAYS_SOLID, Mode.RUPTURA_SHIFT:
			solid_in_target = true
		Mode.ECHO_ONLY:
			solid_in_target = (target_state == ResonanceSystem.State.ECO)
		Mode.PRESENT_ONLY:
			solid_in_target = (target_state == ResonanceSystem.State.PRESENTE)
	if not solid_in_target:
		return false
	var my_rect := Rect2(global_position - size * 0.5, size)
	return my_rect.intersects(world_rect)

func _on_state_changed(new_state: int, _prev: int) -> void:
	_apply_state(new_state)

func _apply_state(state_id: int) -> void:
	match object_mode:
		Mode.ALWAYS_SOLID:
			_set_solid(true)
			if _visual_rect:
				_visual_rect.modulate = Color(1, 1, 1, 1)
		Mode.ECHO_ONLY:
			var is_echo := state_id == ResonanceSystem.State.ECO
			_set_solid(is_echo)
			if _shader_mat:
				_shader_mat.set_shader_parameter("resonance_state", 1 if is_echo else 0)
				_shader_mat.set_shader_parameter("transition_progress", 1.0 if is_echo else 0.18)
			if _visual_rect:
				_visual_rect.modulate = Color(1.0, 0.85, 0.62, 0.92 if is_echo else 0.16)
		Mode.PRESENT_ONLY:
			var is_pres := state_id == ResonanceSystem.State.PRESENTE
			_set_solid(is_pres)
			if _shader_mat:
				_shader_mat.set_shader_parameter("resonance_state", 0 if is_pres else 1)
				_shader_mat.set_shader_parameter("transition_progress", 1.0 if is_pres else 0.14)
			if _visual_rect:
				_visual_rect.modulate = Color(0.88, 0.91, 0.96, 1.0 if is_pres else 0.14)
		Mode.RUPTURA_SHIFT:
			_set_solid(true)
			var is_rup := state_id == ResonanceSystem.State.RUPTURA
			_target_pos = _origin_pos + ruptura_offset if is_rup else _origin_pos
			if _shader_mat:
				_shader_mat.set_shader_parameter("resonance_state", 2 if is_rup else 0)
			if _visual_rect:
				_visual_rect.modulate = Color(1.0, 0.72, 0.42, 1.0) if is_rup else Color(0.92, 0.94, 0.98, 1.0)

func _set_solid(enabled: bool) -> void:
	if collision_shape:
		collision_shape.set_deferred("disabled", not enabled)

extends Area2D
class_name ResonanceSwitch

enum SwitchType { UNLOCK_ECO, UNLOCK_RUPTURA, PUZZLE_ANCHOR, FREQUENCY_SWITCH, CHAPTER_THRESHOLD }

@export var switch_type: SwitchType = SwitchType.PUZZLE_ANCHOR
@export var anchor_id: String = "anchor_1"

var _activated: bool = false
var _t: float = 0.0

@onready var shard_poly: Polygon2D = $ShardPoly
@onready var node_light: PointLight2D = $NodeLight

func _ready() -> void:
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)
	_restore_activated_state()

func _process(delta: float) -> void:
	_t += delta
	if shard_poly:
		shard_poly.position.y = -44.0 + sin(_t * 2.8) * 3.5
	queue_redraw()

func _draw() -> void:
	var cy := -44.0 + sin(_t * 2.8) * 3.5
	var col := Color(0.49, 0.88, 0.66, 0.55) if _activated else Color(0.96, 0.66, 0.26, 0.52)
	var ang := _t * (0.65 if _activated else 1.15)
	draw_arc(Vector2(0.0, cy), 17.0, ang, ang + PI * 1.25, 16, col, 1.4)
	draw_arc(Vector2(0.0, cy), 17.0, ang + PI * 1.45, ang + PI * 1.9, 8, col, 1.4)

func _restore_activated_state() -> void:
	match switch_type:
		SwitchType.UNLOCK_ECO:
			_activated = ResonanceSystem.unlocked_echo
		SwitchType.UNLOCK_RUPTURA:
			_activated = ResonanceSystem.unlocked_ruptura
		SwitchType.PUZZLE_ANCHOR:
			_activated = ResonanceSystem.is_anchor_active(anchor_id)
		SwitchType.FREQUENCY_SWITCH:
			_activated = ResonanceSystem.frequency_switch_active
		SwitchType.CHAPTER_THRESHOLD:
			_activated = false
	_update_visual()

func _update_visual() -> void:
	if shard_poly:
		shard_poly.color = Color(0.49, 0.88, 0.66, 1.0) if _activated else Color(0.96, 0.66, 0.26, 1.0)
	if node_light:
		node_light.color = Color(0.49, 0.88, 0.66, 1.0) if _activated else Color(0.96, 0.64, 0.24, 1.0)
		node_light.energy = 1.1 if _activated else 1.5

func _on_body_entered(body: Node) -> void:
	if body is PlayerController:
		(body as PlayerController).set_nearby_interactable(self)

func _on_body_exited(body: Node) -> void:
	if body is PlayerController:
		(body as PlayerController).set_nearby_interactable(null)

func interact(_player: PlayerController) -> void:
	if _activated and switch_type != SwitchType.CHAPTER_THRESHOLD:
		return
	_activated = true
	_update_visual()
	AudioManager.play_sfx("checkpoint", 1.1)

	match switch_type:
		SwitchType.UNLOCK_ECO:
			ResonanceSystem.unlock_state(ResonanceSystem.State.ECO)
			ResonanceSystem.set_state(ResonanceSystem.State.ECO)
			GameManager.request_cinematic_focus(global_position + Vector2(0, -36), 1.18, 1.15, false)
		SwitchType.UNLOCK_RUPTURA:
			ResonanceSystem.unlock_state(ResonanceSystem.State.RUPTURA)
			ResonanceSystem.set_state(ResonanceSystem.State.RUPTURA)
			GameManager.request_cinematic_focus(global_position + Vector2(0, -36), 1.18, 1.15, false)
		SwitchType.PUZZLE_ANCHOR:
			ResonanceSystem.register_puzzle_anchor(anchor_id, true)
			if ResonanceSystem.puzzle_bridge_locked:
				for gate in get_tree().get_nodes_in_group("ruptura_gates"):
					if gate is RupturaGate and (gate as RupturaGate).permanent_when_puzzle_solved:
						GameManager.request_cinematic_focus(gate.global_position + Vector2(0, -85), 1.02, 1.45, true)
						break
		SwitchType.FREQUENCY_SWITCH:
			ResonanceSystem.set_frequency_switch(true)
		SwitchType.CHAPTER_THRESHOLD:
			GameManager.request_cinematic_focus(global_position + Vector2(70, -85), 0.92, 1.5, true)
			await get_tree().create_timer(1.3).timeout
			if is_inside_tree():
				GameManager.complete_chapter()

extends Node

signal state_changed(new_state: int, previous_state: int)
signal state_unlocked(state_id: int)
signal state_rejected
signal resonance_rejected
signal ruptura_energy_changed(ratio: float)
signal puzzle_node_updated(activated_count: int, total_required: int)
signal frequency_switch_changed(active: bool)

enum State { PRESENTE = 0, ECO = 1, RUPTURA = 2 }

var current_state: int = State.PRESENTE
var unlocked_echo: bool = false
var unlocked_ruptura: bool = false

var ruptura_energy: float = 1.0
@export var ruptura_drain_per_sec: float = 0.14
@export var ruptura_recharge_per_sec: float = 0.28

var puzzle_anchors: Dictionary = {}
var puzzle_bridge_locked: bool = false
var frequency_switch_active: bool = false

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_PAUSABLE

func _process(delta: float) -> void:
	if current_state == State.RUPTURA:
		ruptura_energy = maxf(0.0, ruptura_energy - ruptura_drain_per_sec * delta)
		emit_signal("ruptura_energy_changed", ruptura_energy)
		if ruptura_energy <= 0.0:
			if not set_state(State.PRESENTE, true, false):
				set_state(State.ECO if unlocked_echo else State.PRESENTE, true, true)
	elif ruptura_energy < 1.0:
		ruptura_energy = minf(1.0, ruptura_energy + ruptura_recharge_per_sec * delta)
		emit_signal("ruptura_energy_changed", ruptura_energy)

func _get_player_rect() -> Rect2:
	var players := get_tree().get_nodes_in_group("player")
	if players.is_empty():
		return Rect2()
	var p := players[0]
	if p is Node2D:
		var pos := (p as Node2D).global_position
		return Rect2(pos.x - 8.0, pos.y - 48.0, 16.0, 44.0)
	return Rect2()

func would_overlap_player(target_state: int) -> bool:
	var p_rect := _get_player_rect()
	if p_rect.size == Vector2.ZERO:
		return false
	for obj in get_tree().get_nodes_in_group("resonance_objects"):
		if obj and obj.has_method("would_block_rect_in_state"):
			if obj.would_block_rect_in_state(p_rect, target_state):
				return true
	for gate in get_tree().get_nodes_in_group("ruptura_gates"):
		if gate and gate.has_method("would_block_rect_in_state"):
			if gate.would_block_rect_in_state(p_rect, target_state):
				return true
	return false

func set_state(target_state: int, save_change: bool = true, force: bool = false) -> bool:
	if target_state == current_state:
		return true
	if target_state == State.ECO and not unlocked_echo:
		return false
	if target_state == State.RUPTURA and (not unlocked_ruptura or ruptura_energy < 0.15):
		return false
	if not force and would_overlap_player(target_state):
		emit_signal("state_rejected")
		emit_signal("resonance_rejected")
		AudioManager.play_sfx("ruptura", 0.58)
		return false
	var prev := current_state
	current_state = target_state
	emit_signal("state_changed", current_state, prev)
	AudioManager.play_resonance_transition(current_state)
	if save_change and SaveManager.has_saved_game():
		SaveManager.save_progress()
	return true

func unlock_state(target_state: int) -> void:
	if target_state == State.ECO and not unlocked_echo:
		unlocked_echo = true
		emit_signal("state_unlocked", State.ECO)
		SaveManager.save_progress()
	elif target_state == State.RUPTURA and not unlocked_ruptura:
		unlocked_ruptura = true
		emit_signal("state_unlocked", State.RUPTURA)
		SaveManager.save_progress()

func set_frequency_switch(active: bool, persist: bool = true) -> void:
	frequency_switch_active = active
	emit_signal("frequency_switch_changed", active)
	if persist:
		SaveManager.save_progress()

func get_required_anchors() -> int:
	return 2 if GameManager.current_chapter == 1 else 3

func register_puzzle_anchor(anchor_id: String, active: bool, persist: bool = true) -> void:
	puzzle_anchors[anchor_id] = active
	var required := get_required_anchors()
	var count := 0
	for key in puzzle_anchors.keys():
		if puzzle_anchors[key]:
			count += 1
	puzzle_bridge_locked = count >= required
	emit_signal("puzzle_node_updated", count, required)
	if persist:
		SaveManager.save_progress()

func is_anchor_active(anchor_id: String) -> bool:
	return bool(puzzle_anchors.get(anchor_id, false))

func prepare_chapter(chapter_num: int) -> void:
	unlocked_echo = chapter_num >= 2
	unlocked_ruptura = chapter_num >= 2
	current_state = State.PRESENTE
	ruptura_energy = 1.0
	puzzle_anchors.clear()
	puzzle_bridge_locked = false
	frequency_switch_active = false
	emit_signal("state_unlocked", State.ECO if unlocked_echo else -1)
	if unlocked_ruptura:
		emit_signal("state_unlocked", State.RUPTURA)
	emit_signal("frequency_switch_changed", false)
	emit_signal("puzzle_node_updated", 0, get_required_anchors())
	emit_signal("ruptura_energy_changed", 1.0)
	emit_signal("state_changed", current_state, current_state)

func prepare_chapter_2() -> void:
	prepare_chapter(2)

func restore_from_save(saved: Dictionary) -> void:
	unlocked_echo = bool(saved.get("unlocked_echo", false))
	unlocked_ruptura = bool(saved.get("unlocked_ruptura", false))
	ruptura_energy = clampf(float(saved.get("ruptura_energy", 1.0)), 0.0, 1.0)
	frequency_switch_active = bool(saved.get("frequency_switch_active", false))

	var required := get_required_anchors()
	puzzle_anchors.clear()
	var anchors = saved.get("puzzle_anchors", [])
	var count := 0
	if typeof(anchors) == TYPE_ARRAY:
		for a in anchors:
			var aid := str(a)
			puzzle_anchors[aid] = true
			count += 1
	puzzle_bridge_locked = bool(saved.get("puzzle_bridge_locked", false)) or count >= required

	var saved_state := int(saved.get("resonance_state", State.PRESENTE))
	if saved_state == State.ECO and not unlocked_echo:
		saved_state = State.PRESENTE
	elif saved_state == State.RUPTURA and (not unlocked_ruptura or ruptura_energy < 0.15):
		saved_state = State.PRESENTE

	var prev := current_state
	current_state = saved_state
	emit_signal("state_unlocked", State.ECO if unlocked_echo else -1)
	emit_signal("frequency_switch_changed", frequency_switch_active)
	emit_signal("puzzle_node_updated", count, required)
	emit_signal("ruptura_energy_changed", ruptura_energy)
	emit_signal("state_changed", current_state, prev)

func reset_states() -> void:
	current_state = State.PRESENTE
	unlocked_echo = false
	unlocked_ruptura = false
	ruptura_energy = 1.0
	puzzle_anchors.clear()
	puzzle_bridge_locked = false
	frequency_switch_active = false
