class_name VegetationCluster

@export var width: float = 80.0
@export var blade_count: int = 12
@export var base_color: Color = Color(0.22, 0.34, 0.28, 0.85)

var _t: float = 0.0
var _bend_impulse: float = 0.0

func _process(delta: float) -> void:
	_t += delta
	var players := get_tree().get_nodes_in_group("player")
	if not players.is_empty() and players[0] is PlayerController:
		var p := players[0] as PlayerController
		var dx := p.global_position.x - global_position.x
		if absf(dx) < width * 0.65 and absf(p.global_position.y - global_position.y) < 36.0:
			_bend_impulse = clampf(p.velocity.x * 0.045, -12.0, 12.0)
	_bend_impulse = lerpf(_bend_impulse, 0.0, clampf(delta * 4.0, 0.0, 1.0))
	queue_redraw()

func _draw() -> void:
	for i in range(blade_count):
		var frac := (float(i) / maxf(1.0, float(blade_count - 1))) - 0.5
		var bx := frac * width
		var h := 14.0 + fmod(float(i * 7), 11.0)
		var sway := sin(_t * 1.9 + float(i) * 0.7) * 3.0 + _bend_impulse
		draw_line(Vector2(bx, 0.0), Vector2(bx + sway, -h), base_color, 1.8)

shader_type canvas_item;

uniform vec4 core_color : source_color = vec4(0.95, 0.64, 0.24, 1.0);
uniform float pulse_intensity : hint_range(0.2, 2.5) = 1.0;

void fragment() {
	vec2 centered = UV - vec2(0.5);
	float dist = length(centered) * 2.0;
	float halo = exp(-dist * 3.2) * pulse_intensity;
	float center_dot = smoothstep(0.24, 0.05, dist);
	float alpha = clamp(halo * 0.75 + center_dot, 0.0, 1.0);
	vec3 rgb = mix(core_color.rgb, vec3(1.0, 0.92, 0.76), center_dot * 0.8);
	COLOR = vec4(rgb, alpha);
}

shader_type canvas_item;

// Shader leve para Adreno 619 (single-pass): transição visual entre PRESENTE, ECO e RUPTURA
uniform int resonance_state : hint_range(0, 2) = 0; // 0 = PRESENTE, 1 = ECO, 2 = RUPTURA
uniform float transition_progress : hint_range(0.0, 1.0) = 1.0;
uniform vec4 amber_color : source_color = vec4(0.898, 0.596, 0.220, 1.0);
uniform float pulse_speed = 2.2;

void fragment() {
	vec2 uv = UV;
	vec4 tex = texture(TEXTURE, uv);
	float t = TIME * pulse_speed;

	if (resonance_state == 1) {
		// ECO: Silhueta translúcida com borda âmbar e linhas de memória sutis
		float scan = 0.85 + 0.15 * sin(uv.y * 48.0 - t);
		float edge_x = min(uv.x, 1.0 - uv.x);
		float edge_y = min(uv.y, 1.0 - uv.y);
		float border = 1.0 - smoothstep(0.01, 0.06, min(edge_x, edge_y));
		vec3 eco_tint = mix(tex.rgb * vec3(0.72, 0.65, 0.55), amber_color.rgb, 0.35 + border * 0.55);
		COLOR = vec4(eco_tint * scan, tex.a * (0.68 + border * 0.28) * transition_progress);
	} else if (resonance_state == 2) {
		// RUPTURA: Distorção espacial sutil e realce âmbar-cobre nas arestas
		float wave = sin(uv.y * 24.0 + t * 1.8) * 0.008;
		vec4 shifted = texture(TEXTURE, clamp(uv + vec2(wave, 0.0), 0.0, 1.0));
		float rim = abs(sin((uv.x + uv.y) * 18.0 - t));
		vec3 rup_col = mix(shifted.rgb, amber_color.rgb * 1.15, 0.25 + rim * 0.2);
		COLOR = vec4(rup_col, shifted.a);
	} else {
		// PRESENTE: Preto mineral e cinza frio
		COLOR = tex;
	}
}

shader_type canvas_item;

// Névoa volumétrica simulada de baixo custo para hardware intermediário Android
uniform vec4 fog_color : source_color = vec4(0.14, 0.16, 0.20, 0.35);
uniform vec4 resonance_tint : source_color = vec4(0.898, 0.596, 0.220, 0.14);
uniform float resonance_mix : hint_range(0.0, 1.0) = 0.0;
uniform float drift_speed = 0.025;
uniform float density : hint_range(0.0, 1.0) = 0.55;

float hash(vec2 p) {
	return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
	vec2 i = floor(p);
	vec2 f = fract(p);
	vec2 u = f * f * (3.0 - 2.0 * f);
	return mix(
		mix(hash(i + vec2(0.0, 0.0)), hash(i + vec2(1.0, 0.0)), u.x),
		mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
		u.y
	);
}

void fragment() {
	vec2 uv = UV;
	float n1 = noise(uv * vec2(3.5, 2.0) + vec2(TIME * drift_speed, 0.0));
	float n2 = noise(uv * vec2(7.0, 4.0) - vec2(TIME * drift_speed * 0.6, TIME * 0.008));
	float mist = (n1 * 0.65 + n2 * 0.35) * density;
	float vertical_fade = smoothstep(0.0, 0.35, uv.y) * smoothstep(1.0, 0.25, uv.y);
	vec4 col = mix(fog_color, resonance_tint, resonance_mix);
	COLOR = vec4(col.rgb, col.a * mist * vertical_fade);
}

shader_type canvas_item;

// Reflexo 2D simulado e ondulação leve na superfície da água para Adreno 619
uniform vec4 deep_water_color : source_color = vec4(0.025, 0.034, 0.048, 0.92);
uniform vec4 highlight_color : source_color = vec4(0.898, 0.596, 0.220, 0.24);
uniform float resonance_mix : hint_range(0.0, 1.0) = 0.0;
uniform float wave_speed = 1.8;

void fragment() {
	vec2 uv = UV;
	float t = TIME * wave_speed;
	float ripple1 = sin(uv.x * 38.0 + t + uv.y * 14.0) * 0.5 + 0.5;
	float ripple2 = sin(uv.x * 84.0 - t * 1.4) * 0.5 + 0.5;
	float surface_line = smoothstep(0.08, 0.0, uv.y);
	float depth_grad = smoothstep(0.0, 1.0, uv.y);

	vec3 base = mix(deep_water_color.rgb * 1.35, deep_water_color.rgb * 0.55, depth_grad);
	float spec = (ripple1 * 0.6 + ripple2 * 0.4) * (1.0 - depth_grad * 0.85);
	vec3 glint = mix(vec3(0.32, 0.38, 0.48), highlight_color.rgb * 1.4, 0.35 + resonance_mix * 0.65);

	vec3 final_col = base + glint * (spec * 0.22 + surface_line * 0.35);
	COLOR = vec4(final_col, deep_water_color.a);
}

